/* Free orbit controls for the enlarged SVG camera. */
let orbitZoom=1,orbitPan={x:0,y:0};
const baseUpdate3D=update3D;
update3D=function(){baseUpdate3D();const svg=$('#sceneLarge svg');if(svg){svg.style.transform=`translate(${orbitPan.x}px,${orbitPan.y}px) scale(${orbitZoom})`;svg.style.transformOrigin='center';}for(const [name,value] of [['Obrót modelu 3D',sceneYaw],['Nachylenie modelu 3D',sceneTilt]]){const input=document.querySelector(`[aria-label="${name}"]`);if(input)input.value=Math.round(value*180/Math.PI)}};
function resetOrbit(){sceneYaw=-.65;sceneTilt=.62;orbitZoom=1;orbitPan={x:0,y:0};update3D()}
const oldOpen3D=open3D;
open3D=function(scope){oldOpen3D(scope);const host=$('#sceneLarge');host.tabIndex=0;host.setAttribute('aria-label','Orbita 3D — przeciągnij, aby obrócić; strzałki obracają, plus i minus przybliżają');const hint=document.createElement('div');hint.className='orbit-help';hint.innerHTML='<span>Przeciągnij: obrót 360° · kółko / dwa palce: zoom · Shift + przeciągnij: przesuń</span><button onclick="resetOrbit()">Reset widoku</button>';host.before(hint);const tilt=document.querySelector('[aria-label="Nachylenie modelu 3D"]');tilt.min=-180;tilt.max=180;const pointers=new Map();let gesture=null;const wrap=v=>Math.atan2(Math.sin(v),Math.cos(v));function state(){const p=[...pointers.values()];return {x:p.reduce((s,q)=>s+q.x,0)/p.length,y:p.reduce((s,q)=>s+q.y,0)/p.length,d:p.length===2?Math.hypot(p[1].x-p[0].x,p[1].y-p[0].y):0,n:p.length}}
host.onpointerdown=e=>{if(e.button!==0)return;host.focus({preventScroll:true});pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});host.setPointerCapture(e.pointerId);gesture=state();host.classList.add('orbit-dragging')};host.onpointermove=e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const next=state();if(gesture&&gesture.n===next.n){if(next.n===2){if(gesture.d>0)orbitZoom=clamp(orbitZoom*next.d/gesture.d,.35,5);orbitPan.x+=next.x-gesture.x;orbitPan.y+=next.y-gesture.y}else if(e.shiftKey){orbitPan.x+=next.x-gesture.x;orbitPan.y+=next.y-gesture.y}else{sceneYaw=wrap(sceneYaw+(next.x-gesture.x)*.008);sceneTilt=wrap(sceneTilt+(next.y-gesture.y)*.008)}update3D()}gesture=next};const end=e=>{pointers.delete(e.pointerId);gesture=pointers.size?state():null;if(!pointers.size)host.classList.remove('orbit-dragging')};host.onpointerup=end;host.onpointercancel=end;host.onlostpointercapture=end;host.addEventListener('wheel',e=>{e.preventDefault();orbitZoom=clamp(orbitZoom*Math.exp(-e.deltaY*.001),.35,5);update3D()},{passive:false});host.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key))return;e.preventDefault();if(e.key==='Home')return resetOrbit();if(e.key==='ArrowLeft')sceneYaw=wrap(sceneYaw-.1);if(e.key==='ArrowRight')sceneYaw=wrap(sceneYaw+.1);if(e.key==='ArrowUp')sceneTilt=wrap(sceneTilt-.1);if(e.key==='ArrowDown')sceneTilt=wrap(sceneTilt+.1);if(e.key==='+'||e.key==='=')orbitZoom=clamp(orbitZoom*1.1,.35,5);if(e.key==='-')orbitZoom=clamp(orbitZoom/1.1,.35,5);update3D()};update3D()};
function pro100Dialog(){modal(`<h2>Eksport do PRO100</h2><p>Pakiet ZIP · rozdzielone elementy OBJ + MTL · mm</p><label>Zakres<select id="objScope"><option value="room">Wybrane pomieszczenie</option><option value="all">Cały lokal</option></select></label><label>Grubość ścian na zewnątrz obrysu · mm<input id="objThickness" type="number" min="1" max="1000" value="100"></label><p class="muted">Grubość jest umowna i wspólna dla eksportu. Wymiary wnętrza pozostają zgodne z pomiarem. Sąsiednie przegrody mogą na siebie zachodzić.</p><label><input type="checkbox" id="objCeiling">Dołącz sufit</label><label><input type="checkbox" id="objPoints" checked>Dołącz punkty instalacji: krzyżyk 80 mm + osobny punkt REF 5 mm</label><p>W PRO100: <b>Plik → Import → Model 3D</b>, rozpakuj ZIP, wybierz <b>KiMapka.obj</b> i jednostkę <b>mm</b>. Zaznacz <b>Rozdziel bryły po materiale</b>. Plik KiMapka.mtl musi pozostać obok OBJ. Jeśli powierzchnie znikają, wybierz orientację dwustronną.</p><p>Każda ściana i każdy punkt mają osobny materiał do rozdzielenia przy imporcie. Czerwony znacznik <b>REF</b> ma minimalny narożnik dokładnie w zmierzonym punkcie. W paczce znajdziesz też osobne pliki elementów oraz tabele współrzędnych.</p><p class="muted">To niezależne siatki, nie natywne parametryczne obiekty PRO100. Nie potwierdzono przyciągania do wierzchołka REF. Osobne pliki wymagają ustawienia pozycji według CSV. Import w Twojej wersji PRO100 wymaga sprawdzenia.</p><div class="dialog-actions"><button onclick="closeDialog()">Zamknij</button><button class="primary" onclick="downloadOBJ()">Pobierz pakiet ZIP</button></div>`)}
function downloadOBJ(){try{const t=Number($('#objThickness').value);if(!Number.isFinite(t)||t<1||t>1000)throw Error('Wpisz grubość od 1 do 1000 mm.');const rooms=$('#objScope').value==='all'?data.rooms:[room()];for(const r of rooms)for(const e of r.elements)if(!Geom.elementFits(r,e))throw Error('Najpierw popraw element poza powierzchnią: '+elName(e));const files=Pro100Package.files(rooms,{thickness:t,ceiling:$('#objCeiling').checked,points:$('#objPoints').checked}),url=URL.createObjectURL(new Blob([Pro100Package.zip(files)],{type:'application/zip'})),a=document.createElement('a');a.href=url;a.download='KiMapka-PRO100-rozdzielone.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Pobrano ZIP. Rozpakuj i zaznacz w PRO100: Rozdziel bryły po materiale.')}catch(e){toast(e.message)}}
